/* Visual layer: progressive enhancement; all existing product actions are retained. */
const visualThemes={dashboard:['از ایده تا اثرگذاری','یک فضای کار، برای همهٔ بازوهای برند شما.','growth','کشف فرصت‌های رشد'],studio:['ایده‌ها را دیدنی کن','خلق، بازبینی و انتشار؛ در یک استودیوی مشترک.','calendar','دیدن تقویم محتوا'],inbox:['هر گفتگو، یک ارتباط تازه','با کمک دستیار، پاسخ را بساز و خودت تأییدش کن.','knowledge','آموزش دستیار'],automations:['جریان‌هایی که به هم می‌رسند','یک مسیر بصری از پیام مخاطب تا پاسخ و پیگیری.','knowledge','منابع دستیار'],analytics:['تصویر بزرگ‌تر رشد','از دیدن اعداد تا پیدا کردن قدم بعدی.','growth','انتخاب آزمایش بعدی'],audience:['آدم‌ها، فراتر از اعداد','گفتگوهای بهتر از شناخت مخاطب شروع می‌شوند.','inbox','دیدن گفتگوها'],channels:['همهٔ شبکه‌ها، یک مرکز','بازوهای ارتباطی برندت را یک‌جا مدیریت کن.','studio','ساخت محتوا'],calendar:['ریتم انتشار برندت','ایده‌های امروز، محتوای روزهای آینده.','studio','رفتن به استودیو'],growth:['ایده‌هایی برای حرکت','از یک سؤال واقعی، یک فرصت تازه بساز.','inbox','کشف سؤال مخاطبان'],knowledge:['به دستیار، شناخت بده','دانش برند تو، نقطهٔ شروع پاسخ‌های بهتر.','growth','دیدن پیشنهادها'],sales:['از ارتباط تا تجربهٔ خرید','محصول، سفارش و پیگیری در کنار هم.','inbox','گفتگو با مخاطبان'],onboarding:['برندت را به جریان بینداز','قدم‌به‌قدم فضای کار خودت را بساز.','channels','دیدن شبکه‌ها'],team:['چند نگاه، یک مسیر','ایده، بازبینی و همکاری با هویت مشترک.','studio','میز محتوای تیم'],settings:['امضای برند شما','یک هویت منسجم در تمام ارتباط‌ها.','knowledge','صدای دستیار'],plans:['فضای بیشتر برای رشد','مسیر مناسب تیم خود را پیدا کنید.','growth','کاوش امکانات'],help:['کنارت هستیم','از ایدهٔ اول تا قدم بعدی.','onboarding','راهنمای شروع']};
function visualScene(page){if(['channels','inbox','audience'].includes(page))return `<div class="network-constellation" aria-hidden="true"><div class="constellation-center">${octopusIcon()}</div>${['instagram','telegram','whatsapp','youtube','linkedin','facebook'].map((n,i)=>`<span class="constellation-node node-${i}">${social(n)}</span>`).join('')}</div>`;if(['studio','calendar','sales'].includes(page))return `<div class="visual-deck" aria-hidden="true"><div class="deck-card deck-one">${icon('camera')}<i></i><b></b></div><div class="deck-card deck-two">${icon('calendar')}<div class="deck-dots">${'<i></i>'.repeat(12)}</div></div><div class="deck-card deck-three">${octopusIcon()}<span>ایدهٔ بعدی تو</span></div></div>`;return `<div class="mascot-scene" aria-hidden="true"><div class="mascot-halo"></div>${octopusIcon()}<span class="scene-chip chip-one">${icon('camera')} خلق</span><span class="scene-chip chip-two">${icon('inbox')} ارتباط</span><span class="scene-chip chip-three">${icon('chart')} رشد</span><i class="scene-pearl"></i></div>`}
function visualCover(page){const t=visualThemes[page]||visualThemes.dashboard;return `<section class="visual-cover ${page==='dashboard'?'visual-cover-large':''}"><div class="visual-cover-copy"><span class="visual-eyebrow"><i></i> HASHTIVA · CREATIVE WORKSPACE</span><h2>${t[0]}</h2><p>${t[1]}</p><button class="visual-cta" data-page="${t[2]}">${t[3]} ${icon('arrow')}</button><div class="palette-signature" aria-label="پالت هشتیوا: سرمه‌ای، بنفش، فیروزه‌ای، مرجانی، خاکستری آبی و سفید ابری">${['ocean','indigo','teal','coral','slate','cloud'].map(c=>`<i class="swatch-${c}"></i>`).join('')}<span>الهام‌گرفته از دنیای هشت‌پا</span></div></div>${visualScene(page)}</section>`}
function visualChart(){const values=insightRange==='month'?[110,81,53]:[42,28,19],max=Math.max(...values);return `<section class="visual-report surface"><div><span class="tag blue">دادهٔ نمونه</span><h3>کدام محتوا گفتگو ساخت؟</h3><p>تعداد شروع گفتگو در بازهٔ انتخاب‌شده</p></div><div class="visual-bars">${values.map((v,i)=>`<div class="visual-bar-row"><span>${['راهنمای هدیه','پشت صحنه','پرسش‌های ارسال'][i]}</span><div class="visual-bar-track"><i style="width:${v/max*100}%;--bar:${['#6A5ACD','#14B8A6','#FF8A5B'][i]}"></i></div><b>${fa(v)}</b></div>`).join('')}</div></section>`}
const beforeVisualRender=render;
render=function(page='dashboard'){beforeVisualRender(page);main.insertAdjacentHTML('afterbegin',visualCover(current));if(current==='analytics')main.querySelector('.overview-metrics')?.insertAdjacentHTML('afterend',visualChart());if(current==='growth')document.querySelectorAll('.opportunity').forEach((el,i)=>el.insertAdjacentHTML('afterbegin',`<div class="opportunity-art art-variant-${i%3}" aria-hidden="true">${icon(['camera','inbox','chart'][i%3])}<span>${octopusIcon()}</span></div>`));if(current==='automations')document.querySelectorAll('.flow-route').forEach(el=>el.querySelectorAll('span').forEach((node,i)=>node.insertAdjacentHTML('afterbegin',icon(['inbox','spark','users'][i%3]))));};
render(location.hash.slice(1)||'dashboard');
